/// <summary>
///  The <c>METSalesOrderExtractionBusinessEvent</c> class extends <c>BusinessEventsBase</c> to provide sales order extract business event.
/// </summary>
[BusinessEvents(classStr(METSalesOrderExtractionBusinessEventContract),
    "@MET:SalesOrderExtractionBusinessEventName",
    "@MET:SalesOrderExtractionBusinessEventDesc",
    ModuleAxapta::SalesOrder)]
public final class METSalesOrderExtractionBusinessEvent extends BusinessEventsBase
{
    private WMSPickingRoute wmsPickingRoute;

}

Method.Source:
    /// <summary>
    /// Constructs a new METSalesOrderExtractionBusinessEvent business event.
    /// </summary>
    /// <param name = "_wmsPickingRoute">The <c>WMSPickingRoute</c> record.</param>
    /// <returns>A new <c>METSalesOrderExtractionBusinessEvent</c> business event.</returns>
    public static METSalesOrderExtractionBusinessEvent newFromWMSPickingRoute(WMSPickingRoute _wmsPickingRoute)
    {
        METSalesOrderExtractionBusinessEvent event = new METSalesOrderExtractionBusinessEvent();
        event.parmWMSPickingRoute(_wmsPickingRoute);

        return event;
    }

/// <summary>
/// Gets and sets <c>WMSPickingRoute</c>.
/// </summary>
/// <param name = "_wmsPickingRoute">
/// <c>WMSPickingRoute</c>.
/// </param>
/// <returns>
/// <c>WMSPickingRoute</c>.
/// </returns>
private WMSPickingRoute parmWMSPickingRoute(WMSPickingRoute _wmsPickingRoute = wmsPickingRoute)
{
    wmsPickingRoute = _wmsPickingRoute;
    return wmsPickingRoute;
}

/// <summary>
/// Constructs a new METSalesOrderExtractionBusinessEventContract business event data contract.
/// </summary>
/// <returns>
/// A new <c>METSalesOrderExtractionBusinessEventContract</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
protected BusinessEventsContract buildContract()
{
    return METSalesOrderExtractionBusinessEventContract::newFromWMSPickingRoute(wmsPickingRoute);
}
